def canIWin(maxChoosableInteger: int, desiredTotal: int) -> bool:
    if desiredTotal <= 0: return True
    if (maxChoosableInteger * (maxChoosableInteger + 1)) // 2 < desiredTotal: return False
    memo = {}
    def dfs(used_mask, rem):
        if used_mask in memo: return memo[used_mask]
        for i in range(1, maxChoosableInteger + 1):
            mask = 1 << i
            if not (used_mask & mask):
                if i >= rem or not dfs(used_mask | mask, rem - i):
                    memo[used_mask] = True
                    return True
        memo[used_mask] = False
        return False
    return dfs(0, desiredTotal)

